using System;
using System.IO;
using System.Collections.Generic;
using FreeRdpWrapper.Models;

namespace FreeRdpWrapper.Services
{
    /// <summary>
    /// Parses standard Microsoft Remote Desktop (.rdp) configuration files
    /// generated by mstsc.exe or Remote Desktop Services.
    /// </summary>
    public static class RdpFileParser
    {
        public static SavedConnection Parse(string filePath)
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException("RDP file not found", filePath);

            var lines = File.ReadAllLines(filePath);
            var dict = new Dictionary<string, (string Type, string Value)>(StringComparer.OrdinalIgnoreCase);

            foreach (var rawLine in lines)
            {
                var line = rawLine.Trim();
                if (string.IsNullOrEmpty(line) || line.StartsWith('#'))
                    continue;

                // Format: key:type:value (e.g. "full address:s:192.168.1.10:3389")
                int firstColon = line.IndexOf(':');
                if (firstColon <= 0) continue;

                string key = line.Substring(0, firstColon).Trim();
                string rest = line.Substring(firstColon + 1);

                int secondColon = rest.IndexOf(':');
                if (secondColon <= 0) continue;

                string type = rest.Substring(0, secondColon).Trim();
                string value = rest.Substring(secondColon + 1).Trim();

                dict[key] = (type, value);
            }

            var conn = new SavedConnection
            {
                Name = Path.GetFileNameWithoutExtension(filePath),
                Group = "Imported RDP"
            };

            // Full address: host[:port]
            if (dict.TryGetValue("full address", out var fullAddr) && !string.IsNullOrEmpty(fullAddr.Value))
            {
                conn.Host = fullAddr.Value;
            }

            // Username & Domain
            if (dict.TryGetValue("username", out var user))
            {
                conn.User = user.Value;
            }
            if (dict.TryGetValue("domain", out var dom))
            {
                conn.Domain = dom.Value;
            }

            // Resolution
            if (dict.TryGetValue("desktopwidth", out var w) && int.TryParse(w.Value, out int width))
            {
                conn.ResolutionWidth = width;
                conn.UseCustomResolution = true;
            }
            if (dict.TryGetValue("desktopheight", out var h) && int.TryParse(h.Value, out int height))
            {
                conn.ResolutionHeight = height;
                conn.UseCustomResolution = true;
            }

            // Dynamic resolution & smart sizing
            if (dict.TryGetValue("dynamic resolution", out var dynRes) && dynRes.Value == "1")
            {
                conn.DynamicResolution = true;
            }

            // Audio redirection (0 = local, 1 = remote, 2 = none)
            if (dict.TryGetValue("audiomode", out var audio))
            {
                conn.EnableSound = audio.Value == "0";
            }

            // Clipboard
            if (dict.TryGetValue("redirectclipboard", out var clip))
            {
                conn.EnableClipboard = clip.Value == "1";
            }

            // Printers & Smartcards
            if (dict.TryGetValue("redirectprinters", out var print))
            {
                conn.MapPrinter = print.Value == "1";
            }
            if (dict.TryGetValue("redirectsmartcards", out var sc))
            {
                conn.MapSmartcard = sc.Value == "1";
            }

            // Gateway settings
            if (dict.TryGetValue("gatewayhostname", out var gwHost) && !string.IsNullOrEmpty(gwHost.Value))
            {
                conn.EnableGateway = true;
                conn.GatewayHost = gwHost.Value;
            }

            // RemoteApp
            if (dict.TryGetValue("remoteapplicationprogram", out var app) && !string.IsNullOrEmpty(app.Value))
            {
                conn.RemoteApp = app.Value;
            }

            // Administrative session
            if (dict.TryGetValue("administrative session", out var admin))
            {
                conn.AdminSession = admin.Value == "1";
            }

            // Multimonitor
            if (dict.TryGetValue("use multimon", out var multi))
            {
                conn.MultiMonitor = multi.Value == "1";
            }

            return conn;
        }

        public static string ExportToRdpString(SavedConnection conn)
        {
            var sb = new System.Text.StringBuilder();
            sb.AppendLine($"full address:s:{conn.Host}");
            if (!string.IsNullOrEmpty(conn.User)) sb.AppendLine($"username:s:{conn.User}");
            if (!string.IsNullOrEmpty(conn.Domain)) sb.AppendLine($"domain:s:{conn.Domain}");
            if (conn.UseCustomResolution)
            {
                sb.AppendLine($"desktopwidth:i:{conn.ResolutionWidth}");
                sb.AppendLine($"desktopheight:i:{conn.ResolutionHeight}");
                sb.AppendLine("screen mode id:i:1");
            }
            else
            {
                sb.AppendLine("screen mode id:i:2");
            }
            sb.AppendLine($"dynamic resolution:i:{(conn.DynamicResolution ? 1 : 0)}");
            sb.AppendLine($"redirectclipboard:i:{(conn.EnableClipboard ? 1 : 0)}");
            sb.AppendLine($"redirectprinters:i:{(conn.MapPrinter ? 1 : 0)}");
            sb.AppendLine($"redirectsmartcards:i:{(conn.MapSmartcard ? 1 : 0)}");
            sb.AppendLine($"audiomode:i:{(conn.EnableSound ? 0 : 2)}");
            if (conn.EnableGateway && !string.IsNullOrEmpty(conn.GatewayHost))
            {
                sb.AppendLine($"gatewayhostname:s:{conn.GatewayHost}");
                sb.AppendLine("gatewayusagemethod:i:1");
            }
            if (conn.AdminSession) sb.AppendLine("administrative session:i:1");
            if (conn.MultiMonitor) sb.AppendLine("use multimon:i:1");
            return sb.ToString();
        }
    }
}

